\paragraph{Proof of Lemma~ef{lem:isoperi_implies_A_control}:} We take  egin{align*} T_1 =  rac{1}{32768 q \alpha^2 \log(\ensuremath{d}) \ensuremath{d}^{2 eta}}, \quad T_2 =  rac{\ensuremath{d}^{ eta/(4q)}}{40} T_1 =  rac{1}{ 1310720 q \alpha^2\log(\ensuremath{d}) \ensuremath{d}^{2 eta -  eta/(4q)}}. \end{align*} We bound the spectral norm of $A^{-1/2}A_t A^{-1/2}$ in two time intervals via Lemma~ef{lem:poten_h_bound} and Lemma~ef{lem:poten_f_bound}. In the first time interval $[0, T_1]$, we have  egin{align} \ensuremath{{\mathbb{P}}}\parenth{\int_0^{T_1} \vecnorm{A^{-1/2}A_t A^{-1/2}}{2} \geq  rac{1}{128}} &\leq \ensuremath{{\mathbb{P}}}\parenth{\max_{t \in [0, T_1]} \vecnorm{A^{-1/2}A_t A^{-1/2}}{2} \geq  rac{1}{128T_1}} 
otag \ &\stackrel{(i)}{\leq} \ensuremath{{\mathbb{P}}}\parenth{\max_{t \in [0, T_1]} \vecnorm{A^{-1/2}A_t A^{-1/2}}{2} \geq 3 \ensuremath{d}^{1/q}} 
otag \ &\stackrel{(ii)}{\leq} \ensuremath{{\mathbb{P}}}\parenth{\max_{t \in [0, T_1]} \Gamma_t \geq 3^{q} \ensuremath{d}} 
otag \ &\stackrel{(iii)}{\leq} \ensuremath{{\mathbb{P}}}\parenth{\max_{t \in [0, T_1]} \Gamma_t + 1 \geq 2^{q} (\ensuremath{d}+1)} 
otag \ &\stackrel{\phantom{(iii)}}{=} \ensuremath{{\mathbb{P}}}\parenth{\max_{t \in [0, T_1]} h(\Gamma_t) \geq - rac{1}{2} \parenth{\ensuremath{d}+1}^{-1/q}} 
otag \ &\stackrel{(iv)}{\leq}  rac{3}{10}. \end{align} Inequality (i) follows from the condition $ eta q \geq 1$. (ii) follows from the fact that $\mathrm{Tr}\parenth{A^q}^{1/q} \geq \vecnorm{A}{2}$. (iii) is because $3^q \ensuremath{d} \geq 2^q (\ensuremath{d} + 1)$ when $q \geq 2$ and $\ensuremath{d} \geq 1$. $h$ is defined in Lemma~ef{lem:poten_h_bound}. (iv) follows from Lemma~ef{lem:poten_h_bound}. In the first time interval, we can also bound the expectation of $\Gamma_{T_1}^{1/q}$. Since the density $p_{T_1}$ is more log-concave than a Gaussian density with covariance matrix $ rac{A}{T_1}$, the covariance matrix of $p_{T_1}$ is upper bounded as follows (see Theorem 4.1 in Brascamp-Lieb~\cite{brascamp2002extensions} or Lemma 5 in Eldan and Lehec~\cite{eldan2014bounding})  egin{align} A_{T_1} \preceq  rac{A}{T_1}. \end{align} Consequently, all the eigenvalues of $Q_{T_1}$ are less than $ rac{1}{T_1}$ and $\Gamma_{T_1}$ is upper bounded by $ rac{\ensuremath{d}}{T_1^{q}}$. Using the above bound, we can bound the expectation of $\Gamma_{T_1}^{1/q}$ as follows  egin{align} \ensuremath{{\mathbb{E}}} rackets{\Gamma_{T_1}^{1/q}} &= \ensuremath{{\mathbb{E}}} rackets{\mathbbm{1}_{\Gamma_{T_1} \geq 3^q \ensuremath{d}} \Gamma_{T_1}^{1/q} + \mathbbm{1}_{\Gamma_{T_1} < 3^q \ensuremath{d}} \Gamma_{T_1}^{1/q} } 
otag \ &\stackrel{(i)}{\leq}  rac{\ensuremath{d}^{1/q}}{T_1} \exp\parenth{-  rac{2}{3} q \log(\ensuremath{d})} + 3 \ensuremath{d}^{1/q} 
otag \ &\stackrel{(ii)}{\leq} 32768 \ensuremath{d}^{1/q} q \alpha^2 + 4 \ensuremath{d}^{1/q} 
otag \ &\leq 40000 \ensuremath{d}^{1/q} q \alpha^2. \end{align} Inequality (i) follows from Lemma~ef{lem:poten_h_bound}, the inequality $3^q\ensuremath{d} \geq 2^q(\ensuremath{d}+1)$ (similar to what we did in the last four steps of Equation~\eqref{eq:spec_norm_first_time_period}) and Equation~\eqref{eq:covAt_bound}. (ii) follows from $q \geq 2$, $ eta \leq {1/2}$ and $\ensuremath{d}^{1/2} \geq \log(\ensuremath{d})$ for $\ensuremath{d} \geq 3$. In the second time interval, for $t \in [T_1, T_2]$, we have  egin{align} \ensuremath{{\mathbb{E}}} rackets{\vecnorm{A^{-1/2} A_{t} A^{-1/2}}{2}} &\leq \ensuremath{{\mathbb{E}}} rackets{\Gamma_{t}^{1/q}} 
otag \ &\stackrel{(i)}{\leq} \ensuremath{{\mathbb{E}}} rackets{\Gamma_{T_1}^{1/q}} \parenth{ rac{t}{T_1}}^{2q} 
otag \ &\stackrel{(ii)}{\leq} \ensuremath{{\mathbb{E}}} rackets{\Gamma_{T_1}^{1/q}} \parenth{ rac{T_2}{T_1}}^{2q} 
otag \ &\stackrel{(iii)}{\leq} 1000 \ensuremath{d}^{ eta/2 + 1/q} q \alpha^2 \end{align} Inequality (i) follows from Lemma~ef{lem:poten_f_bound}. (ii) is because $t \leq T_2$. (iii) follows from $T_2 =  rac{\ensuremath{d}^{ eta/(4q)}}{40} T_1$. Using the above bound, we control the spectral norm in the second time interval via Markov's inequality  egin{align} \ensuremath{{\mathbb{P}}}\parenth{\int_{T_1}^{T_2} \vecnorm{A^{-1/2}A_t A^{-1/2}}{2} \geq  rac{1}{128}} &\stackrel{(i)}{\leq}  rac{\ensuremath{{\mathbb{E}}}  rackets{\int_{T_1}^{T_2} \vecnorm{A^{-1/2}A_t A^{-1/2}}{2} dt } }{1/128} 
